        enable_safety_checker: false,
        resolution,
        camera_fixed: cameraFixed
    };
    if (aspectRatio && aspectRatio !== 'smart') {
        requestData.aspect_ratio = aspectRatio;
    }
    if (mode === 'reference-to-video') {
        if (images.length > 0) {
